             if (is_array($c) && isset($c['text'])) {
                 $parts[] = $c['text'];
             }
         }
         return implode(' ', $parts);
     }
     return '';
 }

 /** @return iterable<array> */
 function jsonl(string $path): iterable
 {
     if (!is_file($path)) {
         return;
     }

     $handle = fopen($path, 'r');

     if ($handle === false) {
         return;
     }

     try {
         while (($line = fgets($handle)) !== false) {
             $line = trim($line);

             if ($line === '') {
                 continue;
             }

             $j = json_decode($line, true);

             if (is_array($j)) {
                 yield $j;
             }
         }
     } finally {
         fclose($handle);
     }
 }

 /** @return list<array{role:string,content:string}> */
 function extractGrokMessages(string $sessionDir): array
 {
     $messages = [];
     $chatHistory = "{$sessionDir}/chat_history.jsonl";
     foreach (jsonl($chatHistory) as $row) {
         $type = $row['type'] ?? '';
         if (in_array($type, ['user','assistant','system'], true) && isset($row['content'])) {
             $text = is_array($row['content']) ? extractText($row['content']) : (string) $row['content'];
             $messages[] = ['role' => $type, 'content' => $text];
         }
     }
     return $messages;
 }
