267	function loadSoloProcessRow(string $dbPath, int $id): ?array
268	{
269	    try {
270	        $db = new PDO('sqlite:'.$dbPath);
271	        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
272	        $columns = tableColumns($db, 'processes');
273	        $selectedColumns = array_values(array_filter(
274	            ['id', 'name', 'command', 'working_dir', 'kind', 'project_id', 'started_at', 'created_at', 'spawned_at'],
275	            fn (string $column): bool => in_array($column, $columns, true),
276	        ));
277	
278	        if (! in_array('id', $selectedColumns, true)) {
279	            return null;
280	        }
281	
282	        $select = implode(', ', array_map(quoteIdentifier(...), $selectedColumns));
283	        $stmt = $db->prepare("SELECT {$select} FROM processes WHERE id = ?");
284	        $stmt->execute([$id]);
285	        $row = $stmt->fetch(PDO::FETCH_ASSOC);
286	        return $row ?: null;
287	    } catch (Throwable $e) {
288	        return null;
289	    }
290	}
