432	function replaceStagedCaptureDirectory(
433	    string $temp,
434	    string $final,
435	    string $backup,
436	    ?callable $rename = null,
437	): void {
438	    $providerRoot = dirname($final);
439	    assertDirectChildPath($temp, $providerRoot);
440	    assertDirectChildPath($final, $providerRoot);
441	    assertDirectChildPath($backup, $providerRoot);
442	
443	    $rename ??= static fn (string $from, string $to): bool => @rename($from, $to);
444	    $hadFinal = file_exists($final) || is_link($final);
445	
446	    if ($hadFinal) {
447	        assertDirectChildPath($final, $providerRoot);
448	        assertDirectChildPath($backup, $providerRoot);
449	
450	        if (! $rename($final, $backup)) {
451	            throw new RuntimeException("final_to_backup_failed temp={$temp} final={$final} backup={$backup}");
452	        }
453	    }
454	
455	    assertDirectChildPath($temp, $providerRoot);
456	    assertDirectChildPath($final, $providerRoot);
457	
458	    if (! $rename($temp, $final)) {
459	        if (! $hadFinal) {
460	            throw new RuntimeException("temp_to_final_failed_no_backup temp={$temp} final={$final} backup={$backup}");
461	        }
462	
463	        assertDirectChildPath($backup, $providerRoot);
464	        assertDirectChildPath($final, $providerRoot);
465	
466	        if (! $rename($backup, $final)) {
467	            throw new RuntimeException("temp_to_final_and_rollback_failed temp={$temp} final={$final} backup={$backup}");
468	        }
469	
470	        assertDirectChildPath($temp, $providerRoot);
471	        removePathRecursively($temp);
472	
473	        throw new RuntimeException("temp_to_final_failed_rolled_back temp={$temp} final={$final} backup={$backup}");
474	    }
475	
476	    if ($hadFinal) {
477	        assertDirectChildPath($backup, $providerRoot);
478	        removePathRecursively($backup);
479	    }
480	}
