482	function removePathRecursively(string $path): void
483	{
484	    if (is_link($path) || is_file($path)) {
485	        if (! unlink($path)) {
486	            throw new RuntimeException("Unable to remove path: {$path}");
487	        }
488	
489	        return;
490	    }
491	
492	    if (! is_dir($path)) {
493	        return;
494	    }
495	
496	    $iterator = new RecursiveIteratorIterator(
497	        new RecursiveDirectoryIterator($path, RecursiveDirectoryIterator::SKIP_DOTS),
498	        RecursiveIteratorIterator::CHILD_FIRST,
499	    );
500	
501	    foreach ($iterator as $entry) {
502	        if ($entry->isLink() || $entry->isFile()) {
503	            if (! unlink($entry->getPathname())) {
504	                throw new RuntimeException("Unable to remove path: {$entry->getPathname()}");
505	            }
506	
507	            continue;
508	        }
509	
510	        if (! rmdir($entry->getPathname())) {
511	            throw new RuntimeException("Unable to remove directory: {$entry->getPathname()}");
512	        }
513	    }
514	
515	    if (! rmdir($path)) {
516	        throw new RuntimeException("Unable to remove directory: {$path}");
517	    }
518	}
