544	function fileContains(string $path, string $needle): bool
545	{
546	    if (!is_file($path)) {
547	        return false;
548	    }
549	    $fh = fopen($path, 'r');
550	    if ($fh === false) {
551	        return false;
552	    }
553	    while (!feof($fh)) {
554	        $chunk = fread($fh, 8192);
555	        if ($chunk !== false && str_contains($chunk, $needle)) {
556	            fclose($fh);
557	            return true;
558	        }
559	    }
560	    fclose($fh);
