   869	function normalizeCodexCwd(?string $cwd): ?string
   870	{
   871	    if ($cwd === null || trim($cwd) === '') {
   872	        return null;
   873	    }
   874	
   875	    $resolved = realpath($cwd);
   876	
   877	    if ($resolved !== false) {
   878	        return $resolved;
   879	    }
   880	
   881	    $isAbsolute = str_starts_with($cwd, '/');
   882	    $segments = [];
   883	
   884	    foreach (preg_split('~/+~', $cwd) ?: [] as $segment) {
   885	        if ($segment === '' || $segment === '.') {
   886	            continue;
   887	        }
   888	
   889	        if ($segment === '..') {
   890	            if ($segments !== [] && end($segments) !== '..') {
   891	                array_pop($segments);
   892	            } elseif (! $isAbsolute) {
   893	                $segments[] = $segment;
   894	            }
   895	
   896	            continue;
   897	        }
   898	
   899	        $segments[] = $segment;
   900	    }
   901	
   902	    $normalized = ($isAbsolute ? '/' : '').implode('/', $segments);
   903	
   904	    if ($normalized !== '') {
   905	        return $normalized;
   906	    }
   907	
   908	    return $isAbsolute ? '/' : '.';
   909	}
