   911	function codexTimestampCorroboration(mixed $timestamp, mixed $startedAt): string
   912	{
   913	    if ($timestamp === null || $timestamp === '' || $startedAt === null || $startedAt === '') {
   914	        return 'unavailable';
   915	    }
   916	
   917	    $sessionTimestamp = parseCodexTimestamp($timestamp);
   918	    $soloStartedAt = parseCodexTimestamp($startedAt);
   919	
   920	    if ($sessionTimestamp === null || $soloStartedAt === null) {
   921	        return 'malformed';
   922	    }
   923	
   924	    $now = new DateTimeImmutable('now', new DateTimeZone('UTC'));
   925	
   926	    if ($sessionTimestamp > $now || $soloStartedAt > $now) {
   927	        return 'malformed';
   928	    }
   929	
   930	    if ($sessionTimestamp < $soloStartedAt) {
   931	        return 'resumed-predates-start';
   932	    }
   933	
   934	    return 'corroborated';
   935	}
